cd /home/user/rork-app && python3 << 'PYEOF'
import json, urllib.request, urllib.error, base64

TOKEN = "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"
OWNER = "ibb142"
REPO = "rork-global-real-estate-invest"
BRANCH = "main"
API = "https://api.github.com/repos"

def api(url, method='GET', body=None):
    h = {'Authorization': f'token {TOKEN}', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json', 'X-GitHub-Api-Version': '2022-11-28'}
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            raw = r.read()
            if not raw: return r.status, {}
            try: return r.status, json.loads(raw)
            except: return r.status, {'raw': raw.decode('utf-8', errors='replace')[:3000]}
    except urllib.error.HTTPError as e:
        raw = e.read()
        try: return e.code, json.loads(raw) if raw else {}
        except: return e.code, {'raw': raw.decode('utf-8', errors='replace')[:1000]}
    except Exception as e:
        return 0, {'error': str(e)}

# Get HEAD
s, head = api(f"{API}/{OWNER}/{REPO}/git/ref/heads/{BRANCH}")
head_sha = head['object']['sha']
print(f'HEAD: {head_sha[:12]}')

# Commit login.tsx
with open('expo/app/login.tsx', 'rb') as f:
    content = f.read()
print(f'login.tsx size: {len(content)} bytes')

s, blob = api(f"{API}/{OWNER}/{REPO}/git/blobs", 'POST', {
    'content': base64.b64encode(content).decode(),
    'encoding': 'base64'
})
print(f'blob sha: {blob["sha"][:12]}')

s, tree = api(f"{API}/{OWNER}/{REPO}/git/trees", 'POST', {
    'base_tree': head_sha,
    'tree': [{'path': 'expo/app/login.tsx', 'sha': blob['sha'], 'mode': '100644', 'type': 'blob'}]
})
